artifacts.query:
FOR d0 IN payments
  COLLECT payment_type = d0.type INTO qp_group = { metric_0: d0.value }
  LET payment_count = LENGTH(qp_group)
  LET total_amount = SUM(qp_group[*].metric_0)
  RETURN { payment_type: payment_type, payment_count: payment_count, total_amount: total_amount }

FOR d0 IN reviews
  COLLECT qp_all = true INTO qp_group = { metric_0: d0.score }
  LET avg_score = AVERAGE(qp_group[*].metric_0)
  RETURN { avg_score: avg_score }
